# Generate b4-t1b/stage/run.sh from run.py@69fb6cae3db4's guest SCRIPT, by asserted substitutions only.
import re, sys, hashlib
src = open(sys.argv[1]).read()
m = re.search(r"SCRIPT = r'''(.*?)'''", src, re.S); s = m.group(1)
def sub(old, new):
    global s
    assert s.count(old) == 1, old
    s = s.replace(old, new)
sub("#!/bin/sh\ncd /mnt/vm || exit 1\ninsmod capstone_vm.ko __MODULE_ARGS__ || exit 1\n",
    "#!/bin/sh\n# B first board boot, part 2 (spec-silicon PREREG Addendum 14): run.py@69fb6cae3db4's guest SCRIPT, generated by\n"
    "# gen-t1b.py with three asserted substitutions: the working directory is a tmpfs copy of this stage (the board has no\n"
    "# /mnt/vm), the launcher is the batch's, and insmod is guarded (boardvm loaded the module; the board kernel cannot\n"
    "# unload it, so cleanup is false by construction).\n"
    "S=$(cd \"$(dirname \"$0\")\" && pwd)\nV=${SPEC_VEXEC:?set SPEC_VEXEC}\necho \"@@B4-STAGE t1b\"\n"
    "rm -rf /tmp/vm && mkdir -p /tmp/vm && cp \"$S\"/*.dom /tmp/vm/ && ln -s \"$V\" /tmp/vm/capstone-vexec && cd /tmp/vm || exit 1\n"
    "grep -q \"^capstone_vm \" /proc/modules || insmod \"$(dirname \"$V\")/capstone_vm.ko\" || exit 1\n")
sub("echo VIRTUAL_RUNTIME_DONE\n", "cd / && rm -rf /tmp/vm\necho VIRTUAL_RUNTIME_DONE\n")
open(sys.argv[2], "w").write(s)
print("gen-t1b: run.py", hashlib.sha256(src.encode()).hexdigest()[:16], "-> run.sh", hashlib.sha256(s.encode()).hexdigest()[:16])
